import {bossTentacleTips,bossMouth,bossParasite,PARASITE_LASER_OFFSETS} from './enemyAnatomy.js';
export const BOSS_ATTACK={laserDamageMultiplier:2.8,warning:1.1,laserDuration:1.2,laserRadius:22,damageInterval:.3,forceLeakMultiplier:.5};
export function launchBossAttack(state,enemy,type,damageScale=1){
 const angle=enemy.attackHeading??enemy.heading,origin={...enemy.position},cycle=enemy.attackCycle??0;
 if(cycle%2===0&&(enemy.type!=='finalBoss'||enemy.parasiteRevealed))for(const offset of (enemy.type==='finalBoss'?PARASITE_LASER_OFFSETS:[0])){state.shots.push({id:state.nextShot++,enemyType:enemy.type,kind:'bossLaser',position:enemy.type==='finalBoss'?bossParasite(enemy).position:origin,heading:angle+offset,velocity:{x:0,y:0},radius:enemy.type==='finalBoss'?22:14,length:type.shootRange,damage:type.damage*damageScale*BOSS_ATTACK.laserDamageMultiplier,remaining:BOSS_ATTACK.laserDuration,hitCooldown:0});}
 if(enemy.type==='finalBoss'){for(let i=-3;i<=3;i++){const a=angle+i*.22;state.shots.push({id:state.nextShot++,enemyType:enemy.type,kind:'bossOrb',mouth:true,position:bossMouth(enemy),velocity:{x:Math.sin(a)*type.shotSpeed,y:-Math.cos(a)*type.shotSpeed},radius:9,damage:type.damage*damageScale,remaining:9});}for(const [tipIndex,tip] of bossTentacleTips(enemy,state.time??0).entries())for(const offset of (cycle%2===0?[-.14,0,.14]:[-.28,-.14,0,.14,.28])){const a=angle+offset+(tipIndex-1.5)*.025;state.shots.push({id:state.nextShot++,enemyType:enemy.type,kind:'bossOrb',tentacle:tipIndex,position:{...tip},velocity:{x:Math.sin(a)*type.shotSpeed,y:-Math.cos(a)*type.shotSpeed},radius:9,damage:type.damage*damageScale,remaining:6});}}
 else if(cycle%2!==0)for(const ring of [0,1])for(let i=-5;i<=5;i++){const a=angle+i*.16+(ring?.08:0),speed=type.shotSpeed*(ring?.8:1);state.shots.push({id:state.nextShot++,enemyType:enemy.type,kind:'bossOrb',position:{...origin},velocity:{x:Math.sin(a)*speed,y:-Math.cos(a)*speed},radius:enemy.type==='finalBoss'?9:7,damage:type.damage*damageScale,remaining:6});}
 enemy.attackCycle=cycle+1;
}
